Future<void> initializeZIMKit() async {
  WidgetsFlutterBinding.ensureInitialized();

  await ZIMKit().init(
    appID: yourAppID,
    appSign: yourAppSign,
  );

  final errorCode = await ZIMKit().connectUser(
    id: userID,
    name: userName,
  );
  if (errorCode != 0) {
    throw StateError('ZIMKit user connection failed: $errorCode');
  }
}
